import React from 'react';
import {
  TextField,
  Select,
  MenuItem,
  Button,
  FormControl,
  InputLabel,
  Stack,
} from '@mui/material';

const AppointmentForm = ({
  service,
  date,
  time,
  stylist,
  availableStylists,
  availableTimes,
  onDateChange,
  onTimeChange,
  onStylistChange,
  onSubmit,
}) => {
  return (
    <form onSubmit={onSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
        <TextField
          label="Date"
          type="date"
          value={date}
          onChange={onDateChange}
          required
          sx={{ flexGrow: 1 }}
          InputLabelProps={{ shrink: true }}
        />
        <FormControl sx={{ flexGrow: 1 }}>
          <InputLabel id="time-label">Time</InputLabel>
          <Select
            labelId="time-label"
            label="Time"
            value={time}
            onChange={onTimeChange}
            required
          >
            {availableTimes.map((slot) => (
              <MenuItem key={slot} value={slot}>
                {slot}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Stack>

      <FormControl sx={{ flexGrow: 1 }}>
        <InputLabel id="stylist-label">Stylist</InputLabel>
        <Select
          labelId="stylist-label"
          label="Stylist"
          value={stylist}
          onChange={onStylistChange}
          required
          sx={{ width: '100%' }}
        >
          <MenuItem value="">
            <em>None</em>
          </MenuItem>
          {availableStylists.map((stylistObj) => (
            <MenuItem key={stylistObj._id} value={stylistObj._id}>
              {stylistObj.name}
            </MenuItem>
          ))}
        </Select>
      </FormControl>

      <Button
        type="submit"
        variant="contained"
        color="primary"
        sx={{ width: '100%' }}
      >
        Book Appointment
      </Button>
    </form>
  );
};

export default AppointmentForm;
